mapper.select:
SELECT vote FROM 0721acgn.tb_acgn_vote
WHERE client_id = #{clientId}
  AND media_type = #{mediaType}
  AND media_id = #{mediaId}

mapper.delete:
DELETE FROM 0721acgn.tb_acgn_vote
WHERE client_id = #{clientId}
  AND media_type = #{mediaType}
  AND media_id = #{mediaId}

mapper.update:
UPDATE 0721acgn.tb_acgn_vote
SET vote = #{vote}
WHERE client_id = #{clientId}
  AND media_type = #{mediaType}
  AND media_id = #{mediaId}

mapper.select:
SELECT COUNT(*) FROM 0721acgn.tb_acgn_vote
WHERE media_type = #{mediaType}
  AND media_id = #{mediaId}
  AND vote = #{vote}

SELECT id, nickname, avatar, body, created_at AS createdAt
FROM 0721acgn.tb_acgn_comment
WHERE media_type = #{mediaType}
  AND media_id = #{mediaId}
ORDER BY id DESC
LIMIT #{limit}
